;(function() {
  'use strict';
  
  // Performance enhancement: Create a throttled function to prevent excessive API calls
  function throttle(func, limit) {
      let inThrottle;
      return function() {
          const args = arguments;
          const context = this;
          if (!inThrottle) {
              func.apply(context, args);
              inThrottle = true;
              setTimeout(() => inThrottle = false, limit);
          }
      };
  }
  
  // Performance enhancement: Debounce function to wait for user to stop typing
  function debounce(func, wait) {
      let timeout;
      return function() {
          const context = this;
          const args = arguments;
          clearTimeout(timeout);
          timeout = setTimeout(() => {
              func.apply(context, args);
          }, wait);
      };
  }
  
  // Error tracking: Track and report JS errors
  function trackError(error, context) {
      console.error(`Error in ${context}:`, error);
      // In production, you would send this to your error tracking service
  }
  
  // Lazy load images if they exist in the app
  function lazyLoadImages() {
      if ('IntersectionObserver' in window) {
          const imageObserver = new IntersectionObserver((entries, observer) => {
              entries.forEach(entry => {
                  if (entry.isIntersecting) {
                      const image = entry.target;
                      image.src = image.dataset.src;
                      image.classList.remove('lazy');
                      imageObserver.unobserve(image);
                  }
              });
          });
          
          document.querySelectorAll('img.lazy').forEach(img => {
              imageObserver.observe(img);
          });
      } else {
          // Fallback for browsers without intersection observer support
          document.querySelectorAll('img.lazy').forEach(img => {
              img.src = img.dataset.src;
              img.classList.remove('lazy');
          });
      }
  }
  
  // Add focus styles for accessibility
  function setupAccessibility() {
      // Add focus outline for keyboard users only
      document.body.addEventListener('keydown', function(e) {
          if (e.key === 'Tab') {
              document.body.classList.add('keyboard-user');
          }
      });
      
      document.body.addEventListener('mousedown', function() {
          document.body.classList.remove('keyboard-user');
      });
      
      // Ensure all interactive elements have appropriate ARIA attributes
      document.querySelectorAll('.btn, .tab, .close-modal').forEach(el => {
          if (!el.getAttribute('role')) {
              el.setAttribute('role', 'button');
          }
      });
  }
  
  // Enhance form validation and user feedback
  function enhanceFormValidation() {
      const uploadForm = document.getElementById('upload-form');
      if (uploadForm) {
          // Show visual feedback when files are selected
          const pdfFileInput = document.getElementById('pdf-file');
          const dataFileInput = document.getElementById('data-file');
          
          function updateFileStatus(input, label) {
              if (input) {
                  input.addEventListener('change', function() {
                      const fileLabel = this.previousElementSibling;
                      if (this.files.length > 0) {
                          fileLabel.innerHTML = `${fileLabel.innerText.split(':')[0]}: <span class="file-selected">${this.files[0].name}</span>`;
                      } else {
                          fileLabel.innerHTML = `${fileLabel.innerText.split(':')[0]}: `;
                      }
                  });
              }
          }
          
          updateFileStatus(pdfFileInput);
          updateFileStatus(dataFileInput);
      }
  }
  
  // Add messages container for dynamic user feedback
  function setupMessageSystem() {
      const container = document.querySelector('.container');
      if (container) {
          const messagesContainer = document.createElement('div');
          messagesContainer.id = 'messages-container';
          messagesContainer.style.position = 'fixed';
          messagesContainer.style.top = '20px';
          messagesContainer.style.right = '20px';
          messagesContainer.style.zIndex = '9999';
          messagesContainer.style.maxWidth = '300px';
          document.body.appendChild(messagesContainer);
      }
  }
  
  // Show temporary feedback message
  window.showMessage = function(message, type = 'info', duration = 5000) {
      const messagesContainer = document.getElementById('messages-container');
      if (!messagesContainer) return;
      
      const messageElement = document.createElement('div');
      messageElement.className = `message message-${type}`;
      messageElement.innerHTML = `
          <div class="message-content">
              <span class="message-text">${message}</span>
              <button class="message-close">×</button>
          </div>
      `;
      
      messagesContainer.appendChild(messageElement);
      
      // Style the message
      messageElement.style.backgroundColor = type === 'error' ? '#f8d7da' : '#d1e7dd';
      messageElement.style.color = type === 'error' ? '#721c24' : '#0f5132';
      messageElement.style.padding = '10px';
      messageElement.style.marginBottom = '10px';
      messageElement.style.borderRadius = '4px';
      messageElement.style.boxShadow = '0 2px 5px rgba(0,0,0,0.1)';
      messageElement.style.position = 'relative';
      messageElement.style.animation = 'fadeIn 0.3s';
      
      // Add close button handler
      const closeButton = messageElement.querySelector('.message-close');
      closeButton.style.position = 'absolute';
      closeButton.style.top = '5px';
      closeButton.style.right = '10px';
      closeButton.style.background = 'none';
      closeButton.style.border = 'none';
      closeButton.style.cursor = 'pointer';
      closeButton.style.fontSize = '16px';
      
      closeButton.addEventListener('click', function() {
          messageElement.style.animation = 'fadeOut 0.3s';
          setTimeout(() => {
              if (messageElement.parentNode) {
                  messageElement.parentNode.removeChild(messageElement);
              }
          }, 300);
      });
      
      // Auto remove after duration
      setTimeout(() => {
          if (messageElement.parentNode) {
              messageElement.style.animation = 'fadeOut 0.3s';
              setTimeout(() => {
                  if (messageElement.parentNode) {
                      messageElement.parentNode.removeChild(messageElement);
                  }
              }, 300);
          }
      }, duration);
  };
  
  // Add keyboard shortcut support
  function setupKeyboardShortcuts() {
      document.addEventListener('keydown', function(e) {
          // ESC key to close modals
          if (e.key === 'Escape') {
              document.querySelectorAll('.modal').forEach(modal => {
                  if (modal.style.display === 'block') {
                      modal.style.display = 'none';
                  }
              });
          }
          
          // Ctrl+S for quick save (prevent default browser save)
          if (e.ctrlKey && e.key === 's') {
              e.preventDefault();
              const saveButton = document.querySelector('.btn-save');
              if (saveButton && !saveButton.disabled) {
                  saveButton.click();
              }
          }
      });
  }
  
  // Add print support with a dedicated print function
  window.printElement = function(elementId) {
      const element = document.getElementById(elementId);
      if (!element) return;
      
      const printWindow = window.open('', '_blank');
      const printDocument = printWindow.document;
      
      // Copy all stylesheets from current page
      const stylesheets = document.querySelectorAll('link[rel="stylesheet"]');
      stylesheets.forEach(sheet => {
          const newLink = document.createElement('link');
          newLink.rel = 'stylesheet';
          newLink.href = sheet.href;
          printDocument.head.appendChild(newLink);
      });
      
      // Add inline styles
      const inlineStyles = document.querySelectorAll('style');
      inlineStyles.forEach(style => {
          printDocument.head.appendChild(style.cloneNode(true));
      });
      
      // Add content
      printDocument.body.innerHTML = `<div id="print-content">${element.innerHTML}</div>`;
      
      // Add print-specific styles
      const printStyle = document.createElement('style');
      printStyle.textContent = `
          @media print {
              body { margin: 0; padding: 20px; }
              #print-content { width: 100%; }
          }
      `;
      printDocument.head.appendChild(printStyle);
      
      // Print once everything is loaded
      printWindow.addEventListener('load', () => {
          setTimeout(() => {
              printWindow.print();
              printWindow.close();
          }, 300);
      });
  };
  
  // Enhance tables with sorting functionality
  function enhanceTables() {
      document.querySelectorAll('.status-table').forEach(table => {
          if (table.classList.contains('enhanced')) return;
          
          table.classList.add('enhanced');
          
          const headers = table.querySelectorAll('th');
          headers.forEach((header, index) => {
              if (header.classList.contains('no-sort')) return;
              
              header.style.cursor = 'pointer';
              header.title = 'Click to sort';
              
              // Add sorting indicators
              const sortIndicator = document.createElement('span');
              sortIndicator.className = 'sort-indicator';
              sortIndicator.innerHTML = ' ↕';
              sortIndicator.style.opacity = '0.3';
              header.appendChild(sortIndicator);
              
              header.addEventListener('click', function() {
                  const sortDirection = this.getAttribute('data-sort') === 'asc' ? 'desc' : 'asc';
                  
                  // Reset all headers
                  headers.forEach(h => {
                      h.removeAttribute('data-sort');
                      h.querySelector('.sort-indicator').innerHTML = ' ↕';
                      h.querySelector('.sort-indicator').style.opacity = '0.3';
                  });
                  
                  // Set current header
                  this.setAttribute('data-sort', sortDirection);
                  this.querySelector('.sort-indicator').innerHTML = sortDirection === 'asc' ? ' ↑' : ' ↓';
                  this.querySelector('.sort-indicator').style.opacity = '1';
                  
                  // Sort the table
                  const tableBody = table.querySelector('tbody');
                  const rows = Array.from(tableBody.querySelectorAll('tr'));
                  
                  rows.sort((a, b) => {
                      const aValue = a.cells[index].textContent.trim();
                      const bValue = b.cells[index].textContent.trim();
                      
                      // Check if values are numbers
                      const aNum = parseFloat(aValue);
                      const bNum = parseFloat(bValue);
                      
                      if (!isNaN(aNum) && !isNaN(bNum)) {
                          return sortDirection === 'asc' ? aNum - bNum : bNum - aNum;
                      }
                      
                      // Sort as strings
                      return sortDirection === 'asc' 
                          ? aValue.localeCompare(bValue)
                          : bValue.localeCompare(aValue);
                  });
                  
                  // Reorder rows
                  rows.forEach(row => tableBody.appendChild(row));
              });
          });
      });
  }
  
  // Initialize all enhancements when DOM is ready
  document.addEventListener('DOMContentLoaded', function() {
      setupAccessibility();
      enhanceFormValidation();
      setupMessageSystem();
      setupKeyboardShortcuts();
      lazyLoadImages();
      
      // Add mutation observer to enhance dynamically added tables
      const observer = new MutationObserver(function(mutations) {
          mutations.forEach(function(mutation) {
              if (mutation.addedNodes.length) {
                  enhanceTables();
              }
          });
      });
      
      observer.observe(document.body, { childList: true, subtree: true });
      
      // Initialize tables that are already in the DOM
      enhanceTables();
      
      // Initialize tooltips if needed
      if (typeof bootstrap !== 'undefined' && bootstrap.Tooltip) {
          const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]');
          [...tooltipTriggerList].map(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl));
      }
  });
  
  // Add responsive handlers
  window.addEventListener('resize', throttle(function() {
      // Adjust layout based on screen size
      const screenWidth = window.innerWidth;
      
      // For smaller screens, modify table display
      if (screenWidth < 768) {
          document.querySelectorAll('.status-table').forEach(table => {
              table.classList.add('table-responsive');
          });
      } else {
          document.querySelectorAll('.status-table').forEach(table => {
              table.classList.remove('table-responsive');
          });
      }
  }, 250));
  
  // Add CSS animations for the page
  const style = document.createElement('style');
  style.textContent = `
      @keyframes fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
      }
      @keyframes fadeOut {
          from { opacity: 1; transform: translateY(0); }
          to { opacity: 0; transform: translateY(-10px); }
      }
      .keyboard-user *:focus {
          outline: 2px solid #007bff !important;
          outline-offset: 2px !important;
      }
      .file-selected {
          color: #28a745;
          font-weight: bold;
      }
      .message {
          animation-duration: 0.3s;
          animation-fill-mode: both;
      }
      .table-responsive {
          overflow-x: auto;
          -webkit-overflow-scrolling: touch;
      }
  `;
  document.head.appendChild(style);
  
  // Performance optimization: Add idle callback for non-critical tasks
  if ('requestIdleCallback' in window) {
      requestIdleCallback(function() {
          // Preload common images that might be needed later
          const imagesToPreload = ['spinner.gif', 'no_image_found.jpg'];
          imagesToPreload.forEach(img => {
              const image = new Image();
              image.src = `/static/images/${img}`;
          });
      });
  }
})();